#!/bin/sh
# Auto-generated by BridgeMind. Forwards Claude Code lifecycle events to the app
# so it can show per-terminal working/waiting/done state. Safe to delete.
# The app's response body (if any) is echoed as this hook's stdout — that's how
# BridgeMind answers PermissionRequest hooks with an allow decision when
# auto-approve is enabled for this terminal.
[ -z "$BRIDGEMIND_HOOK_URL" ] && exit 0
payload=$(cat)
resp=$(curl -s -m 2 -X POST "$BRIDGEMIND_HOOK_URL" \
-H 'Content-Type: application/json' \
-d "{\"termId\":\"${BRIDGEMIND_TERM_ID}\",\"event\":${payload}}" 2>/dev/null) || exit 0
[ -n "$resp" ] && printf '%s' "$resp"
exit 0
